(() => {
  // Every word on one line: the rich text's sizes made smaller (never
  // larger) until its longest word fits the canvas (a cell's, in a split),
  // as the text's fit only shrinks it to the height and breaks a word that
  // is wider than the box.
  const raw = String(text || '')
  const room = Math.max(1, (context.imageWidth || 800) - 20)
  let size = 32
  let word = 0
  let widest = 0
  const isSize = (arg) => arg.trim() !== '' && Number.isFinite(Number(arg.trim()))
  for (const part of raw.split(/(\^\([^)]*\))/)) {
    const marker = /^\^\(([^)]*)\)$/.exec(part)
    if (marker) {
      for (const arg of marker[1].split(',')) if (isSize(arg)) size = Number(arg.trim())
      continue
    }
    part.split(/\s/).forEach((piece, i) => {
      if (i > 0) word = 0
      word += piece.length * size * 0.62
      widest = Math.max(widest, word)
    })
  }
  const k = Math.min(1, room / Math.max(1, widest))
  if (k >= 1) return raw
  const fit = (n) => String(Math.max(1, Math.floor(n * k)))
  return '^(' + fit(32) + ')' + raw.replace(/\^\(([^)]*)\)/g, (_, args) =>
    '^(' + args.split(',').map((arg) => (isSize(arg) ? fit(Number(arg.trim())) : arg)).join(',') + ')')
})()

(() => {
  // On a round panel the grid goes in the square inside the circle, so no
  // cell has a corner where the glass is not.
  if (context.round !== true || !context.imageWidth) return '10'
  const side = Math.min(context.imageWidth, context.imageHeight || context.imageWidth)
  return String(Math.round(side * 0.15))
})()
